window.bookSummaryJSON = "<p><i>The Caller of the Black</i> is Brian Lumley's first published collection of stories, with many of them involving the Cthulhu Mythos. </p> <p>Stories included in this collection: </p> <ul> <li>\"A Thing About Cars!\"</li> <li>\"The Cyprus Shell\" </li> <li>\"Billy's Oak\"</li> <li>\"The Writer in the Garret\"</li> <li>\"The Caller of the Black\"</li> <li>\"The Mirror of Nitocris\"</li> <li>\"The Night Sea-Maid Went Down\"</li> <li>\"The Thing from the Blasted Heath\"</li> <li>\"An Item of Supporting Evidence\"</li> <li>\"Dylath-Leen\"</li> <li>\"De Marigny's Clock\"</li> <li>\"Ambler's Inspiration\"</li> <li>\"In the Vaults Beneath\"</li> <li>\"The Pearl\"</li> </ul>"; 
